      const i = OpCodes.And32(n, 0xFF);
      const idx1 = OpCodes.And32(keyByte + mem[i], 0xFF);
      const idx2 = OpCodes.And32(T_LOOKUP180[idx1] + runningByte, 0xFF);
      runningByte = mem[idx2];
      const oldTi = mem[i];
      mem[i] = mem[runningByte];
      mem[runningByte] = oldTi;
